INSERT INTO "question" VALUES('real_fgv_2025_ebserh_psicologia_tipo1_q01','qg-conhecimentos-gerais-etica-direitos-documentos-e-politicas-publicas','O primeiro parágrafo do texto, que serve de introdução, tem a finalidade básica de','multiple_choice','unspecified','unspecified','Gabarito definitivo da FGV identificado. A explicação pedagógica individual será revisada com base no item e nas referências da categoria.','real','FGV','EBSERH 2025 — Grupo Psicologia — Tipo 1',2025,1,'https://arquivos.qconcursos.com/prova/arquivo_prova/129217/fgv-2025-ebserh-grupo-psicologia-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/129217/fgv-2025-ebserh-grupo-psicologia-gabarito.pdf','definitivo FGV','published',1,1,0,'real_fgv_2025_ebserh_psicologia_tipo1_q01');
