INSERT INTO "question" VALUES('real-ibfc_mgs_2024_psicologo-026','qg-desenvolvimento-humano-desenvolvimento-aprendizagem-e-cognicao','Sobre o desenvolvimento psicossocial na terceira infância, assinale a alternativa correta.','multiple_choice','unspecified','conceitual','Questão real de prova oficial; comentário pedagógico individual ainda não produzido.','real','IBFC','MGS — Processo Seletivo Público Simplificado, Edital nº 07/2023 — Psicólogo',2024,26,'https://arquivos.qconcursos.com/prova/arquivo_prova/105120/ibfc-2024-mgs-psicologo-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/105120/ibfc-2024-mgs-psicologo-gabarito.pdf','gabarito_oficial_pos_recurso','published',1,1,0,'real-ibfc_mgs_2024_psicologo-026');
INSERT INTO "question" VALUES('real-ibfc_mgs_2024_psicologo-027','qg-desenvolvimento-humano-desenvolvimento-aprendizagem-e-cognicao','Sobre o envelhecimento, analise: I. Existem várias maneiras de vivenciar o envelhecimento e a velhice segundo circunstâncias biológicas, psicológicas, sociais, econômicas, históricas e culturais. PORQUE II. As teorias do envelhecimento são unânimes e não apresentam diferenças entre si. Assinale a alternativa correta.','multiple_choice','unspecified','conceitual','Questão real de prova oficial; comentário pedagógico individual ainda não produzido.','real','IBFC','MGS — Processo Seletivo Público Simplificado, Edital nº 07/2023 — Psicólogo',2024,27,'https://arquivos.qconcursos.com/prova/arquivo_prova/105120/ibfc-2024-mgs-psicologo-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/105120/ibfc-2024-mgs-psicologo-gabarito.pdf','gabarito_oficial_pos_recurso','published',1,1,0,'real-ibfc_mgs_2024_psicologo-027');
