INSERT INTO "question" VALUES('real-fgv_mpsp_2023-060-840cb0cedb38','qg-humanista-existencial-e-fenomenologica-psicanalise-humanismo-e-clinica','Com relação à Gestalt-terapia, assinale a afirmativa correta.','multiple_choice','unspecified','a_revisar','Questão real de prova oficial; comentário ainda não produzido.','real','FGV','Ministério Público do Estado de São Paulo — Concurso Público 2023 — Analista de Promotoria I — Área de Saúde e Assistência Social — Psicólogo — Prova 1',2023,60,'https://conhecimento.fgv.br/sites/default/files/concursos/cns005-analista-de-promotoria-i-area-de-saude-e-assistencia-social-psicologocns005-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/edital-29-2023-analista-de-promotoria-i-gabarito-da-prova-objetiva-pdf.pdf',NULL,'published',1,1,0,'real-fgv_mpsp_2023-060-840cb0cedb38');
