INSERT INTO "question" VALUES('real_cespe_2008_fub_psicologo_escolar_q105','qg-psicologia-escolar-e-educacional-psicologia-escolar-e-educacional','A atuação do psicólogo escolar deve ser concretizada em uma dimensão preventiva, em resposta às reais e complexas demandas que a escola, como instituição sociocultural, lhe apresenta.','true_false','unspecified','unspecified','Gabarito oficial definitivo identificado. A explicação pedagógica individual será revisada com base no item e na bibliografia da categoria.','real','CESPE/CEBRASPE','FUB 2008 — Psicólogo/Área Escolar',2008,105,'https://www.estudegratis.com.br/images/provas/7153-cespe-2008-fub-psicologo-escolar-prova.pdf','https://www.estudegratis.com.br/images/provas/7153-cespe-2008-fub-psicologo-escolar-gabarito.pdf','oficial definitivo','published',1,1,0,'real_cespe_2008_fub_psicologo_escolar_q105');
INSERT INTO "question" VALUES('real_cespe_2008_fub_psicologo_escolar_q106','qg-psicologia-escolar-e-educacional-psicologia-escolar-e-educacional','Mapear e analisar a instituição escolar não é uma etapa básica do processo de intervenção institucional para o qual o psicólogo escolar deve desenvolver competências. Julgue os itens a seguir, acerca dos preconceitos presentes no cotidiano escolar.','true_false','unspecified','unspecified','Gabarito oficial definitivo identificado. A explicação pedagógica individual será revisada com base no item e na bibliografia da categoria.','real','CESPE/CEBRASPE','FUB 2008 — Psicólogo/Área Escolar',2008,106,'https://www.estudegratis.com.br/images/provas/7153-cespe-2008-fub-psicologo-escolar-prova.pdf','https://www.estudegratis.com.br/images/provas/7153-cespe-2008-fub-psicologo-escolar-gabarito.pdf','oficial definitivo','published',1,1,0,'real_cespe_2008_fub_psicologo_escolar_q106');
