INSERT INTO "question" VALUES('real_cespe_2008_fub_psicologo_escolar_q110','qg-psicologia-escolar-e-educacional-psicologia-escolar-e-educacional','Segundo Lajonquière, uma das facetas do processo de psicologização do cotidiano escolar é a ilusão psicopedagógica: os professores imaginam que existem na criança e no adolescente capacidades psicológicas, em estado germinal, que devem ser desenvolvidas por práticas pedagógicas adequadas. Acerca do processo ensino-aprendizagem, julgue os itens de 111 a 117.','true_false','unspecified','unspecified','Gabarito oficial definitivo identificado. A explicação pedagógica individual será revisada com base no item e na bibliografia da categoria.','real','CESPE/CEBRASPE','FUB 2008 — Psicólogo/Área Escolar',2008,110,'https://www.estudegratis.com.br/images/provas/7153-cespe-2008-fub-psicologo-escolar-prova.pdf','https://www.estudegratis.com.br/images/provas/7153-cespe-2008-fub-psicologo-escolar-gabarito.pdf','oficial definitivo','published',1,1,0,'real_cespe_2008_fub_psicologo_escolar_q110');
