INSERT INTO "question" VALUES('real-vunesp_mpe_es_2013_psicologo-075','qg-psicologia-da-saude-sus-e-politicas-publicas-etica-direitos-documentos-e-politicas-publicas','Quando um paciente psiquiátrico apresenta melhoras, é comum que outro membro da família apresente problemas, como crises psicossomáticas ou depressão. Essas ocorrências podem ser atribuídas','multiple_choice','unspecified','conceitual','Item real de prova oficial; comentário pedagógico individual ainda não produzido.','real','VUNESP','MPE/ES 2013 — Agente Técnico — Psicólogo — Prova Objetiva 021',2013,75,'https://arquivos.qconcursos.com/prova/arquivo_prova/31963/vunesp-2013-mpe-es-agente-tecnico-psicologo-prova.pdf','https://arquivos.qconcursos.com/prova/arquivo_gabarito/31963/vunesp-2013-mpe-es-agente-tecnico-psicologo-gabarito.pdf','gabarito_oficial','published',1,1,0,'real-vunesp_mpe_es_2013_psicologo-075');
