INSERT INTO "question_fts_content" VALUES(1470,'real-fgv_enare_2024_2025-005-264ec51463aa','Segundo a Portaria de Consolidação nº 3/2017 do Ministério da
INSERT INTO "question_fts_content" VALUES(1471,'real-fgv_enare_2024_2025-006-002f57aa69a8','A Equipe do Núcleo de Saúde da Família e Atenção Básica
(NASF-AB), como competência específica, deve Questão real de prova oficial; comentário ainda não produzido.');
