INSERT INTO "question_option" VALUES('PSI-BANCO-0046-a','PSI-BANCO-0046',1,'Consistência e estabilidade dos resultados do instrumento ao longo do tempo ou entre formas/avaliadores.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0046-b','PSI-BANCO-0046',2,'A capacidade do instrumento de medir exatamente aquilo que se propõe a medir (validade).',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0046-c','PSI-BANCO-0046',3,'A representatividade da amostra normatizada no manual do teste.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0046-d','PSI-BANCO-0046',4,'A facilidade de aplicação do instrumento por avaliadores leigos.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0046-e','PSI-BANCO-0046',5,'A adequação cultural do conteúdo do instrumento sem necessidade de adaptação.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0047-a','PSI-BANCO-0047',1,'Objetivo da avaliação, possíveis usos dos resultados, limites da confidencialidade, duração prevista, e autorização para registro e divulgação quando necessária.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0047-b','PSI-BANCO-0047',2,'Apenas o tempo aproximado da aplicação e o valor cobrado pelo serviço.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0047-c','PSI-BANCO-0047',3,'Somente o nome dos instrumentos que serão usados, sem explicar seu propósito.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0047-d','PSI-BANCO-0047',4,'Informações detalhadas sobre as notas de outros avaliados para comparação.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0047-e','PSI-BANCO-0047',5,'Nada precisa ser informado; a aplicação pode ocorrer sem consentimento prévio.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0048-a','PSI-BANCO-0048',1,'Um teste normatizado compara o desempenho do indivíduo com o de uma amostra normatizada; um teste baseado em critérios avalia se o indivíduo atingiu um padrão ou critério preestabelecido independentemente da distribuição de escores na população.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0048-b','PSI-BANCO-0048',2,'Testes normatizados são sempre mais válidos que testes baseados em critérios.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0048-c','PSI-BANCO-0048',3,'Testes baseados em critérios só podem ser usados em contextos educacionais, enquanto normatizados são exclusivamente clínicos.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0048-d','PSI-BANCO-0048',4,'Testes normatizados fornecem apenas dados qualitativos, ao passo que critérios geram apenas dados quantitativos.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0048-e','PSI-BANCO-0048',5,'Não há diferença; são termos intercambiáveis.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0336-a','PSI-BANCO-0336',1,'A) Focar apenas na queixa principal para acelerar o diagnóstico.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0336-b','PSI-BANCO-0336',2,'B) Utilizar perguntas abertas, escuta empática e observar a linguagem não verbal.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0336-c','PSI-BANCO-0336',3,'C) Evitar discutir limites de confidencialidade no início.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0336-d','PSI-BANCO-0336',4,'D) Impor um diagnóstico provável para orientar a conversa.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0336-e','PSI-BANCO-0336',5,'E) Encerrar a entrevista quando o paciente demonstra resistência.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0360-a','PSI-BANCO-0360',1,'A) Validade de construto envolve evidências de que as pontuações refletem o constructo pretendido, com suporte de evidências de conteúdo, relação com outras medidas e predição de comportamentos.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0360-b','PSI-BANCO-0360',2,'B) Validade de construto é obtida apenas pela correlação com medidas correlatas.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0360-c','PSI-BANCO-0360',3,'C) Validade de construto é o mesmo que confiabilidade.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0360-d','PSI-BANCO-0360',4,'D) Validade de construto não se aplica a instrumentos de avaliação clínica.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0360-e','PSI-BANCO-0360',5,'E) Validade de construto pode ser comprovada apenas por evidência teórica sem dados empíricos.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0361-a','PSI-BANCO-0361',1,'A) É a capacidade do instrumento de medir exatamente o que pretende medir.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0361-b','PSI-BANCO-0361',2,'B) É a consistência e estabilidade das pontuações, estimadas por medidas como consistência interna e teste-reteste.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0361-c','PSI-BANCO-0361',3,'C) É determinada apenas pela qualidade das normas utilizadas.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0361-d','PSI-BANCO-0361',4,'D) É o grau em que o instrumento diferencia pessoas com base no constructo.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0361-e','PSI-BANCO-0361',5,'E) É a qualidade da aplicação que não depende do avaliador.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0362-a','PSI-BANCO-0362',1,'A) Normas absolutas podem ser usadas sem considerar diferenças culturais ou demográficas.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0362-b','PSI-BANCO-0362',2,'B) Normas devem ser universais e não requerem adaptação cultural.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0362-c','PSI-BANCO-0362',3,'C) Normas devem ser baseadas em amostra representativa da população-alvo, com informações demográficas relevantes, e atualizadas periodicamente.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0362-d','PSI-BANCO-0362',4,'D) Normas pouco influenciam a interpretação clínica e diagnóstico.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0362-e','PSI-BANCO-0362',5,'E) Normas substituem a necessidade de informações sobre validade e confiabilidade.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0363-a','PSI-BANCO-0363',1,'A) Proporcionam diagnóstico definitivo.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0363-b','PSI-BANCO-0363',2,'B) Garantem que o avaliador não precise interpretar.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0363-c','PSI-BANCO-0363',3,'C) Reduzem a influência do avaliador e permitem comparação entre indivíduos.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0363-d','PSI-BANCO-0363',4,'D) São mais fáceis de aplicar sem treinamento.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0363-e','PSI-BANCO-0363',5,'E) Podem ser usados sem considerar a população-alvo.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0364-a','PSI-BANCO-0364',1,'A) Relatar apenas informações que apoiem uma recomendação solicitada.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0364-b','PSI-BANCO-0364',2,'B) Descrever claramente as evidências de validade, confiabilidade e limitações, indicar a finalidade do laudo, o público-alvo e evitar extrapolações.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0364-c','PSI-BANCO-0364',3,'C) Incluir diagnósticos formais sem fundamentação suficiente.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0364-d','PSI-BANCO-0364',4,'D) Excluir quaisquer limitações sobre utilidade do laudo.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0364-e','PSI-BANCO-0364',5,'E) Usar linguagem excessivamente técnica para impressionar o solicitante.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0370-a','PSI-BANCO-0370',1,'A) Garantir que o instrumento seja sensível a mudanças temporais',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0370-b','PSI-BANCO-0370',2,'B) Medir o que se propõe a medir',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0370-c','PSI-BANCO-0370',3,'C) Garantir a confiabilidade entre avaliadores',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0370-d','PSI-BANCO-0370',4,'D) Ser fácil de aplicar',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0370-e','PSI-BANCO-0370',5,'E) Estender seus escores para qualquer população',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0371-a','PSI-BANCO-0371',1,'A) Consistência interna entre itens, independentemente do tempo',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0371-b','PSI-BANCO-0371',2,'B) Consistência entre observadores em apenas uma ocasião',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0371-c','PSI-BANCO-0371',3,'C) Estabilidade dos escores ao longo do tempo',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0371-d','PSI-BANCO-0371',4,'D) Relação entre precisão e validade',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0371-e','PSI-BANCO-0371',5,'E) Capacidade de prever resultados futuros com exatidão',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0372-a','PSI-BANCO-0372',1,'A) Garantir validade de conteúdo',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0372-b','PSI-BANCO-0372',2,'B) Definir o tempo de aplicação',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0372-c','PSI-BANCO-0372',3,'C) Oferecer uma base de comparação para interpretar escores',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0372-d','PSI-BANCO-0372',4,'D) Substituir o manual técnico',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0372-e','PSI-BANCO-0372',5,'E) Ajustar aleatoriamente as notas',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0373-a','PSI-BANCO-0373',1,'A) Utilizar dados apenas de uma fonte para evitar contradicões',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0373-b','PSI-BANCO-0373',2,'B) Registrar consentimento informado, triangular informações quando possível e reportar limitações da entrevista',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0373-c','PSI-BANCO-0373',3,'C) Revelar dados confidenciais indiscriminadamente no laudo',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0373-d','PSI-BANCO-0373',4,'D) Reduzir a entrevista para pouco tempo sem justificativa',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0373-e','PSI-BANCO-0373',5,'E) Desconsiderar filtros de qualidade de dados',0);
