INSERT INTO "question_option" VALUES('PSI-BANCO-0375-b','PSI-BANCO-0375',2,'B) Validade de critério é a evidência de que o teste mede o constructo pretendido, com base em teorias.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0375-c','PSI-BANCO-0375',3,'C) Validade de construto envolve evidências de que o teste mede o constructo pretendido e se relaciona com outros constructos e comportamentos.',1);
