INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0509-e','PSI-AUT-EXP-150-0509',5,'E) Priorizar interesses institucionais sobre o bem-estar da parte avaliada.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0510-a','PSI-AUT-EXP-150-0510',1,'A) Concluir o laudo com base apenas na entrevista com um dos genitores.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0510-b','PSI-AUT-EXP-150-0510',2,'B) Orientar-se por expectativas das partes e buscar confirmar sua opinião pré-estabelecida.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0510-c','PSI-AUT-EXP-150-0510',3,'C) Fundamentar o laudo em dados de múltiplas fontes (entrevistas, observação, documentos) priorizando o melhor interesse da criança.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0510-d','PSI-AUT-EXP-150-0510',4,'D) Substituir-se ao juiz na tomada de decisão.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0510-e','PSI-AUT-EXP-150-0510',5,'E) Considerar confidencialidade como absoluta e não compartilhar informações relevantes com o juiz.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0511-a','PSI-AUT-EXP-150-0511',1,'A) A vontade exclusiva de quem solicitou a guarda.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0511-b','PSI-AUT-EXP-150-0511',2,'B) Vínculos afetivos, capacidade parental, rede de apoio, necessidades e bem-estar da criança, com triangulação de informações (entrevista, relatos, observação, documentos).',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0511-c','PSI-AUT-EXP-150-0511',3,'C) Apenas a opinião do psicólogo sem contraditório.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0511-d','PSI-AUT-EXP-150-0511',4,'D) Excluir a participação da criança na avaliação.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0511-e','PSI-AUT-EXP-150-0511',5,'E) Conceder a guarda ao genitor que pagou a maior quantia.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0512-a','PSI-AUT-EXP-150-0512',1,'A) Apenas documentação administrativa',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0512-b','PSI-AUT-EXP-150-0512',2,'B) Adequação parental, rede de apoio, necessidades da criança e observação da dinâmica familiar.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0512-c','PSI-AUT-EXP-150-0512',3,'C) Decisão com base unicamente na vontade dos pais',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0512-d','PSI-AUT-EXP-150-0512',4,'D) Conduzir apenas entrevista com o casal',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0512-e','PSI-AUT-EXP-150-0512',5,'E) Ignorar histórico de trauma ou riscos.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0513-a','PSI-AUT-EXP-150-0513',1,'A) Não avaliar risco em casos de violência doméstica.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0513-b','PSI-AUT-EXP-150-0513',2,'B) Limitar-se a registrar a queixa sem avaliação de risco.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0513-c','PSI-AUT-EXP-150-0513',3,'C) Realizar avaliação de risco, considerar histórico de violência, comunicar-se com a rede de proteção e priorizar a segurança da vítima.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0513-d','PSI-AUT-EXP-150-0513',4,'D) Encaminhar ao judiciário sem ouvir a vítima.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0513-e','PSI-AUT-EXP-150-0513',5,'E) Pretender atuar apenas com a vítima e o agressor sem rede.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0514-a','PSI-AUT-EXP-150-0514',1,'A) Compartilhar dados com a rede sem consentimento',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0514-b','PSI-AUT-EXP-150-0514',2,'B) Manter sigilo absoluto, sem permitir nenhum compartilhamento',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0514-c','PSI-AUT-EXP-150-0514',3,'C) Estabelecer limites de confidencialidade com consentimento informado e compartilhar informações relevantes com autoridades competentes, priorizando o bem-estar da criança',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0514-d','PSI-AUT-EXP-150-0514',4,'D) Envolver-se emocionalmente com as partes e perder a objetividade',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0514-e','PSI-AUT-EXP-150-0514',5,'E) Excluir-se do caso sem justificativa',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0515-a','PSI-AUT-EXP-150-0515',1,'A) Laudo baseado apenas em entrevistas com uma das partes, sem triangulação de informações nem consulta à rede de proteção.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0515-b','PSI-AUT-EXP-150-0515',2,'B) Laudo utiliza apenas diagnóstico clínico, sem interface com as questões jurídicas.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0515-c','PSI-AUT-EXP-150-0515',3,'C) Laudo fundamenta-se numa avaliação multidisciplinar que integra entrevista, observação do vínculo, análise de documentos e informações de rede de proteção.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0515-d','PSI-AUT-EXP-150-0515',4,'D) Laudo substitui a decisão judicial com base na opinião subjetiva do perito.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0515-e','PSI-AUT-EXP-150-0515',5,'E) Laudo prescinde de fatores contextuais e impactos no direito de convivência.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0516-a','PSI-AUT-EXP-150-0516',1,'A) Interpretação baseada apenas na empatia com um dos genitores e na preferência da escola',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0516-b','PSI-AUT-EXP-150-0516',2,'B) Análise centrada apenas em dados de visitas domiciliares, sem considerar a opinião da criança ou a rede de proteção',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0516-c','PSI-AUT-EXP-150-0516',3,'C) Avaliação abrangente com observação, entrevistas com a criança, pais e rede de proteção, considerando o melhor interesse da criança e a continuidade de vínculos',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0516-d','PSI-AUT-EXP-150-0516',4,'D) Laudo que prioriza a conveniência dos pais sem avaliar o impacto na criança',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0516-e','PSI-AUT-EXP-150-0516',5,'E) Laudo sem considerar a participação da escola ou serviços sociais',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0517-a','PSI-AUT-EXP-150-0517',1,'A) O laudo baseia-se apenas na história parental, sem avaliação de vínculos atuais com a criança adotiva.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0517-b','PSI-AUT-EXP-150-0517',2,'B) A avaliação deve considerar apenas fatores socioeconômicos.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0517-c','PSI-AUT-EXP-150-0517',3,'C) A avaliação envolve entrevista com familiares, observação de interações, checagem de rede de apoio e compatibilidade com as necessidades da criança; a escuta da criança adotiva é parte da prática ética.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0517-d','PSI-AUT-EXP-150-0517',4,'D) O laudo pode ser conclusivo sem considerar limites éticos de confidencialidade.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0517-e','PSI-AUT-EXP-150-0517',5,'E) A adoção não requer avaliação psicológica se os documentos estiverem em ordem.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0518-a','PSI-AUT-EXP-150-0518',1,'A) Laudo que apenas confirme a ocorrência de violência com base em relatos da vítima, sem triangulação de informações.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0518-b','PSI-AUT-EXP-150-0518',2,'B) Avaliação de violência doméstica não deve considerar fatores de risco para crianças no núcleo familiar.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0518-c','PSI-AUT-EXP-150-0518',3,'C) Avaliação integrada com entrevista à vítima, análise de relatos, informações de redes de proteção e avaliação de risco para crianças, com recomendações de proteção.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0518-d','PSI-AUT-EXP-150-0518',4,'D) O psicólogo deve evitar emitir opinião sobre proteção infantil para não se envolver em políticas públicas.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0518-e','PSI-AUT-EXP-150-0518',5,'E) O laudo deve descrever apenas sintomas da vítima, sem orientar medidas de proteção.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0519-a','PSI-AUT-EXP-150-0519',1,'A) O depoimento especial prescinde de qualquer adaptação do ambiente ou da linguagem para a criança.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0519-b','PSI-AUT-EXP-150-0519',2,'B) O psicólogo deve manter a criança sob pressão para obter respostas rápidas.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0519-c','PSI-AUT-EXP-150-0519',3,'C) O depoimento especial envolve entrevista com a criança de forma protegida, com linguagem apropriada, uso de perguntas abertas e sem indução, buscando preservar a espontaneidade do testemunho.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0519-d','PSI-AUT-EXP-150-0519',4,'D) O depoimento é dirigido apenas pela polícia e o psicólogo não intervém na entrevista.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0519-e','PSI-AUT-EXP-150-0519',5,'E) O depoimento especial não envolve avaliação psicológica.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0520-a','PSI-AUT-EXP-150-0520',1,'A) Confidencialidade absoluta sem exceções.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0520-b','PSI-AUT-EXP-150-0520',2,'B) Garantir consentimento informado, esclarecer limites de confidencialidade e comunicar como as informações serão utilizadas no laudo.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0520-c','PSI-AUT-EXP-150-0520',3,'C) Utilizar apenas informações de fontes públicas.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0520-d','PSI-AUT-EXP-150-0520',4,'D) Divulgar informações confidenciais a qualquer parte que solicitar.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0520-e','PSI-AUT-EXP-150-0520',5,'E) Documentar tudo sem comunicar as partes.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0521-a','PSI-AUT-EXP-150-0521',1,'A) Recomendar guarda unilateral para o genitor com maior poder econômico.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0521-b','PSI-AUT-EXP-150-0521',2,'B) Priorizar o interesse superior da criança, considerando vínculos, rede de apoio e possibilidade de convivência com ambos, desde que não haja risco.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0521-c','PSI-AUT-EXP-150-0521',3,'C) Aguardar a decisão judicial sem participação de ambos os genitores.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0521-d','PSI-AUT-EXP-150-0521',4,'D) Basear-se apenas em opinião subjetiva de um dos genitores.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0521-e','PSI-AUT-EXP-150-0521',5,'E) Interromper o contato da criança com ambos os genitores sem fundamentação.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0522-a','PSI-AUT-EXP-150-0522',1,'A) Focar apenas na estabilidade financeira dos adotantes.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0522-b','PSI-AUT-EXP-150-0522',2,'B) Avaliar fatores de proteção e risco, rede de apoio, condições de vida, relação com crianças existentes e adaptabilidade à nova criança, conforme necessidade da criança adotada.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0522-c','PSI-AUT-EXP-150-0522',3,'C) Verificar apenas a relação entre o casal e a criança pretendida para adoção.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0522-d','PSI-AUT-EXP-150-0522',4,'D) Declara aptidão sem observar histórico familiar e rede de apoio.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0522-e','PSI-AUT-EXP-150-0522',5,'E) Excluir a criança do processo de avaliação.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0523-a','PSI-AUT-EXP-150-0523',1,'A) Exigir relato detalhado da violência sem considerar o trauma da criança.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0523-b','PSI-AUT-EXP-150-0523',2,'B) Adotar abordagem centrada na proteção da vítima e da criança, com entrevista adaptada, registro de sinais de trauma e uso de depoimento especial/escuta protegida quando adequado.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0523-c','PSI-AUT-EXP-150-0523',3,'C) Coletar depoimentos apenas de terceiros sem ouvir a vítima.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0523-d','PSI-AUT-EXP-150-0523',4,'D) Realizar avaliação apenas com relatos dos adultos.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0523-e','PSI-AUT-EXP-150-0523',5,'E) Divulgar informações de violência a terceiros sem necessidade.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0524-a','PSI-AUT-EXP-150-0524',1,'A) Aceitar ambas as solicitações e manter neutralidade sem limites bem definidos.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0524-b','PSI-AUT-EXP-150-0524',2,'B) Recusar conflitos de interesse, esclarecer função, manter sigilo e impedir colaborações que comprometam a imparcialidade; quando necessário, recusar e encaminhar para outro profissional.',1);
