INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0525-b','PSI-AUT-EXP-150-0525',2,'B) Declarar o conflito de interesses e solicitar afastamento ou substituição do perito.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0525-c','PSI-AUT-EXP-150-0525',3,'C) Indicar à parte financiadora como a avaliação deve progredir para favorecer sua posição.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0525-d','PSI-AUT-EXP-150-0525',4,'D) Adiar a avaliação indefinidamente sem declarar o conflito.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0525-e','PSI-AUT-EXP-150-0525',5,'E) Publicar um relatório com a avaliação sem mencionar o conflito de interesses.',0);
