INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0526-d','PSI-AUT-EXP-150-0526',4,'D) A disponibilidade de tempo do genitor que reside mais próximo.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0526-e','PSI-AUT-EXP-150-0526',5,'E) A decisão deve favorecer apenas o genitor que reside na casa maior.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0527-a','PSI-AUT-EXP-150-0527',1,'A) Avaliar exclusivamente a capacidade financeira do adotante.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0527-b','PSI-AUT-EXP-150-0527',2,'B) Priorizar a adoção pelo menor tempo de espera, sem avaliação de vínculos.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0527-c','PSI-AUT-EXP-150-0527',3,'C) O melhor interesse da criança, considerando vínculos com pais biológicos, condições de cuidado, histórico de riscos e potencial de adaptação.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0527-d','PSI-AUT-EXP-150-0527',4,'D) Focar apenas na idade do adotante.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0527-e','PSI-AUT-EXP-150-0527',5,'E) Avaliar apenas a entrevista com o adotante, sem observar o ambiente familiar.',0);
