INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0528-c','PSI-AUT-EXP-150-0528',3,'C) Requerer que a vítima relate a versão sem qualquer apoio ou intervenção.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0528-d','PSI-AUT-EXP-150-0528',4,'D) Informar ao agressor sobre o conteúdo do depoimento da vítima.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0528-e','PSI-AUT-EXP-150-0528',5,'E) Encerrar a avaliação sem considerar aspectos de violência.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0529-a','PSI-AUT-EXP-150-0529',1,'A) Realizar o depoimento de forma direta, sem adaptações, como em uma audiência comum.',0);
