INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0777-false','PSI-AUT-EXP-150-0777',2,'Errado',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0778-true','PSI-AUT-EXP-150-0778',1,'Certo',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0778-false','PSI-AUT-EXP-150-0778',2,'Errado',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0779-true','PSI-AUT-EXP-150-0779',1,'Certo',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0779-false','PSI-AUT-EXP-150-0779',2,'Errado',0);
