INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0002-d','PSI-AUT-EXP-150-0002',4,'D) Ambas consideram apenas fatores situacionais.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0002-e','PSI-AUT-EXP-150-0002',5,'E) As duas teorias afirmam que o comportamento é determinado exclusivamente por fatores biológicos.',0);
