INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0012-a','PSI-AUT-EXP-150-0012',1,'A) Os traços são relativamente estáveis ao longo da vida, enquanto a psicodinâmica enfatiza conflitos inconscientes e mudanças ao longo do desenvolvimento.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0012-b','PSI-AUT-EXP-150-0012',2,'B) Traços se baseiam apenas em fatores culturais; psicodinâmica é puramente biológica.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0012-c','PSI-AUT-EXP-150-0012',3,'C) Traços não preveem comportamentos sob pressão; psicodinâmica não considera o inconsciente.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0012-d','PSI-AUT-EXP-150-0012',4,'D) Traços dependem exclusivamente de genética; psicodinâmica determina o comportamento apenas por escolhas conscientes.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0012-e','PSI-AUT-EXP-150-0012',5,'E) Traços são mutáveis com idade e psicodinâmica também.',0);
