INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0015-e','PSI-AUT-EXP-150-0015',5,'E) Temperamento',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0016-a','PSI-AUT-EXP-150-0016',1,'A) O id representa o polo consciente da personalidade, buscando satisfação imediata.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0016-b','PSI-AUT-EXP-150-0016',2,'B) O ego funciona conforme o princípio da realidade, buscando satisfação realista dos impulsos do id.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0016-c','PSI-AUT-EXP-150-0016',3,'C) O superego é composto apenas por pulsões inconscientes que são sempre conflitantes com o mundo externo.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0016-d','PSI-AUT-EXP-150-0016',4,'D) O ego é a instância responsável apenas pela expressão de desejos sociais.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0016-e','PSI-AUT-EXP-150-0016',5,'E) O id regula o comportamento de forma consciente e planeja estratégias de longo prazo.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0017-a','PSI-AUT-EXP-150-0017',1,'A) Freud enfatiza conflitos inconscientes e pulsões; Rogers enfatiza a autoatualização e a experiência do self; Bandura enfatiza a aprendizagem observacional e crenças de eficácia.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0017-b','PSI-AUT-EXP-150-0017',2,'B) Freud foca no comportamento observável; Rogers no inconsciente; Bandura no processamento emocional.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0017-c','PSI-AUT-EXP-150-0017',3,'C) Freud e Rogers compartilham a ideia de que o ambiente externo é o único determinante da personalidade; Bandura discorda.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0017-d','PSI-AUT-EXP-150-0017',4,'D) Bandura propõe uma visão biológica estrita da personalidade, enquanto Freud e Rogers destacam fatores culturais.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0017-e','PSI-AUT-EXP-150-0017',5,'E) Rogers rejeita a ideia de que a autoimagem é central para a personalidade.',0);
