INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0019-c','PSI-AUT-EXP-150-0019',3,'C) Iniciativa vs Culpa',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0019-d','PSI-AUT-EXP-150-0019',4,'D) Identidade vs Confusão de Identidade',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0019-e','PSI-AUT-EXP-150-0019',5,'E) Intimidade vs Isolamento',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0020-a','PSI-AUT-EXP-150-0020',1,'A) Self é apenas o conjunto de regras sociais que a pessoa pretende seguir.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0020-b','PSI-AUT-EXP-150-0020',2,'B) Identidade envolve papéis sociais, valores e metas que definem quem a pessoa é, enquanto o self (autoconceito) reflete as percepções subjetivas de si mesmo.',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0020-c','PSI-AUT-EXP-150-0020',3,'C) Self e identidade são termos sinônimos e não apresentam distinção conceitual.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0020-d','PSI-AUT-EXP-150-0020',4,'D) A identidade não é influenciada pela cultura ou pelo grupo de pares.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0020-e','PSI-AUT-EXP-150-0020',5,'E) O self não pode mudar ao longo do tempo.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0021-a','PSI-AUT-EXP-150-0021',1,'A) Controlar apenas impulsos sexuais',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0021-b','PSI-AUT-EXP-150-0021',2,'B) Reunir o superego para reforçar a moral',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0021-c','PSI-AUT-EXP-150-0021',3,'C) Mediar entre desejos do id, exigências da realidade e normas morais do superego',1);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0021-d','PSI-AUT-EXP-150-0021',4,'D) Inferir todos os conteúdos conscientes sem influência do inconsciente',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0021-e','PSI-AUT-EXP-150-0021',5,'E) Substituir totalmente o id na determinação do comportamento',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0022-a','PSI-AUT-EXP-150-0022',1,'A) Freud enfatiza a experiência consciente do self como motor da personalidade; Rogers enfatiza o inconsciente como motor principal.',0);
INSERT INTO "question_option" VALUES('PSI-AUT-EXP-150-0022-b','PSI-AUT-EXP-150-0022',2,'B) Freud defende que a personalidade é determinada apenas pela hereditariedade; Rogers sustenta que o comportamento é resultado do condicionamento social.',0);
