INSERT INTO "question_option" VALUES('PSI-BANCO-0320-e','PSI-BANCO-0320',5,'E) Desconsiderar resistência e manter a relação de poder',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0325-a','PSI-BANCO-0325',1,'A) Ignorar a resistência.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0325-b','PSI-BANCO-0325',2,'B) Explorar empataticamente a reação, renegociar o contrato terapêutico e manter o foco na relação terapêutica, respeitando limites éticos.',1);
