INSERT INTO "question_option" VALUES('PSI-BANCO-0325-d','PSI-BANCO-0325',4,'D) Transferir a paciente para outro profissional sem aviso.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0325-e','PSI-BANCO-0325',5,'E) Obrigar a paciente a falar sobre temas desconfortáveis.',0);
