INSERT INTO "question_option" VALUES('PSI-BANCO-0335-b','PSI-BANCO-0335',2,'B) Ignorar a dúvida para não interromper a sessão.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0335-c','PSI-BANCO-0335',3,'C) Encerrar a terapia sem explicação.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0335-d','PSI-BANCO-0335',4,'D) Mudar de terapeuta sem consentimento do paciente.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0335-e','PSI-BANCO-0335',5,'E) Prometer confidencialidade absoluta sem limites.',0);
