INSERT INTO "question_option" VALUES('PSI-BANCO-0340-b','PSI-BANCO-0340',2,'B) Reconhecer a ruptura, solicitar feedback, esclarecer sentimentos e negociar um plano de tratamento com participação do cliente, mantendo limites profissionais.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0340-c','PSI-BANCO-0340',3,'C) Garantir que a aliança está intacta sem discutir dificuldades.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0340-d','PSI-BANCO-0340',4,'D) Encerrar a terapia sem explicação.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0340-e','PSI-BANCO-0340',5,'E) Aumentar a intensidade da intervenção sem consentimento.',0);
