INSERT INTO "question_option" VALUES('PSI-BANCO-0350-d','PSI-BANCO-0350',4,'D) Realizar avaliação multidisciplinar, obter consentimento informado, planejar a transição de cuidado e manter comunicação entre equipes.',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0350-e','PSI-BANCO-0350',5,'E) Encaminhar apenas quando a família solicita.',0);
