INSERT INTO "question_option" VALUES('PSI-BANCO-0399-a','PSI-BANCO-0399',1,'A) Impor a decisão da equipe médica sem considerar a autonomia.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0399-b','PSI-BANCO-0399',2,'B) Buscar o equilíbrio entre autonomia, beneficência, não maleficência e justiça, envolvendo a equipe multiprofissional para consentimento compartilhado.',1);
