INSERT INTO "question_option" VALUES('PSI-BANCO-0404-c','PSI-BANCO-0404',3,'C) decisão compartilhada com respeito à autonomia do paciente, beneficência e não maleficência, envolvendo a equipe multiprofissional',1);
