INSERT INTO "question_option" VALUES('PSI-BANCO-0409-c','PSI-BANCO-0409',3,'C) Impor as preferências da família sem considerar o desejo do paciente.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0409-d','PSI-BANCO-0409',4,'D) Priorizar a eficiência do serviço sobre o bem-estar do paciente.',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0409-e','PSI-BANCO-0409',5,'E) Evitar discutir o tema para não gerar conflito.',0);
