INSERT INTO "question_option" VALUES('PSI-BANCO-0414-b','PSI-BANCO-0414',2,'B) Encobrir a conduta e manipular dados de reabilitação',0);
INSERT INTO "question_option" VALUES('PSI-BANCO-0414-c','PSI-BANCO-0414',3,'C) Garantir avaliação médica independente, comunicar riscos, e retornar somente com autorização clínica, respeitando princípios de beneficência, não maleficência, autonomia e justiça',1);
INSERT INTO "question_option" VALUES('PSI-BANCO-0414-d','PSI-BANCO-0414',4,'D) Delegar a decisão ao supervisor sem consulta clínica',0);
